export function validateEmail(value) {
  if (typeof value !== 'string' || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(value.trim())) return 'email: not a valid address'
  if (value.trim().length > 254) return 'email: longer than 254 characters'
  return null
}

